// @pit: {"label": "Create release branch, commit, push, and open PR"}
async ({ shell: { execFile }, delivery: { commit }, gh: { prCreate } }, p: { body: string }) => {
  await execFile("git", ["switch", "-c", "release-0.37.0"], { raise: true });
  const c = await commit({ files: ["CHANGELOG.md", "README.md", "package.json", "package-lock.json"], message: "chore(release): v0.37.0", push: true });
  const pr = await prCreate({ title: "chore(release): v0.37.0", body: p.body, base: "main", head: "release-0.37.0" } as any);
  return { c, pr: pr.stdout ?? pr };
}
